    77→export async function updateSavedSearchAction(
    78→  request: UpdateSavedSearchRequest,
    79→) {
    80→  const session = await auth.api.getSession({
    81→    headers: await headers(),
    82→  });
    83→
    84→  if (!session?.user.id) {
    85→    redirect("/auth/signin");
    86→  }
    87→
    88→  const savedSearch = await prisma.savedSearch.findFirst({
    89→    where: {
    90→      id: request.id,
    91→      userId: session.user.id,
    92→    },
    93→  });
    94→
    95→  if (!savedSearch) {
    96→    throw new Error("Recherche sauvegardée non trouvée");
    97→  }
    98→
    99→  const updatedSearch = await prisma.savedSearch.update({
   100→    where: {
   101→      id: request.id,
   102→    },
   103→    data: {
   104→      ...(request.name && { name: request.name }),
   105→      ...(request.criteria && { criteria: request.criteria }),
   106→      ...(typeof request.isActive !== "undefined" && {
   107→        isActive: request.isActive,
   108→      }),
   109→      ...(request.frequency && { frequency: request.frequency }),
   110→    },
   111→  });
   112→
   113→  console.debug(
   114→    `✅ [SavedSearches] Updated "${updatedSearch.name}" for user ${session.user.id}`,
   115→  );
   116→
   117→  revalidatePath("/alerts");
   118→
   119→  return updatedSearch;
   120→}
