     1→import jsPDF from "jspdf";
     2→import "jspdf-autotable";
     3→import type { NegotiationReport, PDFExportOptions } from "../types";
     4→
     5→/**
     6→ * Service d'export PDF pour les rapports de négociation
     7→ */
     8→export class PDFExportService {
     9→  private readonly colors = {
    10→    primary: "#1f2937",
    11→    secondary: "#6b7280",
    12→    accent: "#3b82f6",
    13→    success: "#10b981",
    14→    warning: "#f59e0b",
    15→    danger: "#ef4444",
    16→  };
    17→
    18→  /**
    19→   * Génère un PDF du rapport de négociation
    20→   */
    21→  generatePDF(
    22→    report: NegotiationReport,
    23→    options: PDFExportOptions = {
    24→      includeCharts: true,
    25→      includeComparables: true,
    26→      includeFullAnalysis: true,
    27→    },
    28→  ): void {
    29→    const doc = new jsPDF("p", "mm", "a4");
    30→    let yPosition = 20;
    31→
    32→    // Configuration des polices
    33→    doc.setFont("helvetica");
    34→
    35→    // En-tête du document
    36→    yPosition = this.addHeader(doc, report, yPosition);
    37→
    38→    // Résumé exécutif
    39→    yPosition = this.addExecutiveSummary(doc, report, yPosition);
    40→
    41→    // Stratégie de négociation (page principale)
    42→    yPosition = this.addNegotiationStrategy(doc, report, yPosition);
    43→
    44→    // Nouvelle page pour les arguments détaillés
    45→    if (options.includeFullAnalysis && report.arguments.length > 0) {
    46→      doc.addPage();
    47→      yPosition = 20;
    48→      yPosition = this.addDetailedArguments(doc, report, yPosition);
    49→    }
    50→
    51→    // Nouvelle page pour l'analyse de marché
    52→    if (options.includeFullAnalysis) {
    53→      doc.addPage();
    54→      yPosition = 20;
    55→      yPosition = this.addMarketAnalysis(doc, report, yPosition);
    56→    }
    57→
    58→    // Notes personnalisées
    59→    if (options.customNotes) {
    60→      if (yPosition > 250) {
    61→        doc.addPage();
    62→        yPosition = 20;
    63→      }
    64→      yPosition = this.addCustomNotes(doc, options.customNotes, yPosition);
    65→    }
    66→
    67→    // Pied de page sur toutes les pages
    68→    this.addFooter(doc);
    69→
    70→    // Téléchargement du fichier
    71→    const fileName = `rapport-negociation-${report.property.city}-${new Date().getTime()}.pdf`;
    72→    doc.save(fileName);
    73→  }
    74→
    75→  /**
    76→   * Ajoute l'en-tête du document
    77→   */
    78→  private addHeader(
    79→    doc: jsPDF,
    80→    report: NegotiationReport,
    81→    yPosition: number,
    82→  ): number {
    83→    // Titre principal
    84→    doc.setFontSize(20);
    85→    doc.setTextColor(this.colors.primary);
    86→    doc.text("RAPPORT DE NÉGOCIATION", 105, yPosition, { align: "center" });
    87→    yPosition += 15;
    88→
    89→    // Informations du bien
    90→    doc.setFontSize(12);
    91→    doc.setTextColor(this.colors.secondary);
    92→    doc.text(report.property.title, 105, yPosition, { align: "center" });
    93→    yPosition += 6;
    94→    doc.text(
    95→      `${report.property.address}, ${report.property.city} (${report.property.postalCode})`,
    96→      105,
    97→      yPosition,
    98→      { align: "center" },
    99→    );
   100→    yPosition += 10;
   101→
   102→    // Prix et date
   103→    doc.setFontSize(10);
   104→    doc.text(
   105→      `Prix annoncé: ${this.formatPrice(report.property.price)}`,
   106→      20,
   107→      yPosition,
   108→    );
   109→    doc.text(
   110→      `Généré le: ${report.generatedAt.toLocaleDateString("fr-FR")}`,
   111→      190,
   112→      yPosition,
   113→      { align: "right" },
   114→    );
   115→    yPosition += 15;
   116→
   117→    // Ligne de séparation
   118→    doc.setDrawColor(200, 200, 200);
   119→    doc.line(20, yPosition, 190, yPosition);
   120→    yPosition += 10;
   121→
   122→    return yPosition;
   123→  }
   124→
   125→  /**
   126→   * Ajoute le résumé exécutif
   127→   */
   128→  private addExecutiveSummary(
   129→    doc: jsPDF,
   130→    report: NegotiationReport,
   131→    yPosition: number,
   132→  ): number {
   133→    doc.setFontSize(14);
   134→    doc.setTextColor(this.colors.primary);
   135→    doc.text("RÉSUMÉ EXÉCUTIF", 20, yPosition);
   136→    yPosition += 10;
   137→
   138→    // Score et potentiel
   139→    doc.setFontSize(11);
   140→    const potentialText = {
   141→      high: "Élevé",
   142→      medium: "Moyen",
   143→      low: "Faible",
   144→    };
   145→
   146→    doc.setTextColor(this.colors.accent);
   147→    doc.text(
   148→      `Score de négociation: ${report.summary.overallScore}/100`,
   149→      20,
   150→      yPosition,
