    10→
    11→/**
    12→ * Service d'analyse pour la négociation immobilière
    13→ * Génère des arguments factuels basés sur les données DVF, DPE et marché
    14→ */
    15→export class NegotiationAnalysisService {
    16→  private readonly dvfService: DVFService;
    17→
    18→  constructor() {
    19→    this.dvfService = new DVFService();
    20→  }
    21→
    22→  /**
    23→   * Génère un rapport de négociation complet pour une propriété
    24→   */
    25→  async generateNegotiationReport(
    26→    property: Property,
    27→    _userComments?: string,
    28→  ): Promise<NegotiationReport> {
    29→    // 1. Analyse DVF (prix du marché)
    30→    const dvfAnalysis = await this.analyzeDVFComparison(property);
    31→
    32→    // 2. Analyse énergétique
    33→    const energyAnalysis = this.analyzeEnergyPerformance(property);
    34→
    35→    // 3. Contexte marché
    36→    const marketContext = this.analyzeMarketContext(property);
    37→
    38→    // 4. Temps sur le marché
    39→    const timeOnMarket = this.calculateTimeOnMarket(property);
    40→
    41→    // 5. Génération des arguments
    42→    const negotiationArguments = this.generateNegotiationArguments({
    43→      property,
    44→      dvfAnalysis,
    45→      energyAnalysis,
    46→      marketContext,
    47→      timeOnMarket,
    48→    });
    49→
    50→    // 6. Stratégie de négociation
    51→    const strategy = this.calculateNegotiationStrategy({
    52→      property,
    53→      dvfAnalysis,
    54→      energyAnalysis,
    55→      marketContext,
    56→      timeOnMarket,
    57→    });
    58→
    59→    // 7. Score global et résumé
    60→    const summary = this.generateSummary(negotiationArguments, strategy);
    61→
    62→    return {
    63→      property,
    64→      analysis: {
    65→        dvf: dvfAnalysis,
    66→        energy: energyAnalysis,
    67→        market: marketContext,
    68→        timeOnMarket,
    69→      },
    70→      arguments: negotiationArguments,
    71→      strategy,
    72→      summary,
    73→      generatedAt: new Date(),
    74→    };
    75→  }
    76→
    77→  /**
    78→   * Analyse DVF - Comparaison avec le marché local
    79→   */
    80→  private async analyzeDVFComparison(property: Property) {
    81→    if (!property.surface || !property.postalCode) {
    82→      throw new Error(
    83→        "Property must have surface and postal code for DVF analysis",
    84→      );
    85→    }
    86→
    87→    const comparison = await this.dvfService.compareWithMarket(
    88→      property.price,
    89→      property.surface,
    90→      property.category === "apartment" ? "Appartement" : "Maison",
    91→      property.city,
    92→      property.postalCode,
    93→    );
    94→
    95→    if (!comparison.success || !comparison.data) {
    96→      throw new Error("Failed to get DVF comparison");
    97→    }
    98→
    99→    return comparison.data;
   100→  }

